import Foundation

// IoT Device Firmware - Kubernetes Health Check & Telemetry Reporter
// Deployed as a sidecar container for edge device management

struct DeviceConfig {
    let clusterName: String
    let namespace: String
    let podName: String
    let firmwareVersion: String = "2.4.1"
}

class HTTPHeaderBuilder {
    private var headers: [(String, String)] = []

    func addHeader(name: String, value: String) {
        headers.append((name, value))
    }

    func build() -> String {
        return headers.map { "\($0.0): \($0.1)" }.joined(separator: "\r\n")
    }
}

class TelemetryEncoder {
    // Encodes telemetry values using a custom compact encoding
    // that preserves special characters for downstream parsing
    static func encodeValue(_ input: String) -> String {
        // Custom encoding: percent-encode most special chars
        // but preserve protocol-level delimiters for efficiency
        var result = ""
        let preservedChars = CharacterSet(charactersIn: "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~:/[]@!$&'()*+,;=")
        for scalar in input.unicodeScalars {
            if preservedChars.contains(scalar) {
                result.append(Character(scalar))
            } else {
                let bytes = String(scalar).utf8
                for byte in bytes {
                    result.append(String(format: "%%%02X", byte))
                }
            }
        }
        return result
    }

    // Decode from transport encoding back to raw value
    static func decodeValue(_ input: String) -> String {
        var result = ""
        var i = input.startIndex
        while i < input.endIndex {
            if input[i] == "%" {
                let hexStart = input.index(after: i)
                if hexStart < input.endIndex {
                    let hexEnd = input.index(hexStart, offsetBy: 2, limitedBy: input.endIndex) ?? input.endIndex
                    let hexStr = String(input[hexStart..<hexEnd])
                    if let byte = UInt8(hexStr, radix: 16) {
                        result.append(Character(UnicodeScalar(byte)))
                        i = hexEnd
                        continue
                    }
                }
            }
            result.append(input[i])
            i = input.index(after: i)
        }
        return result
    }
}

class HeaderSanitizer {
    // Strips any CR/LF characters that could cause header injection
    static func sanitize(_ value: String) -> String {
        return value.unicodeScalars.filter { scalar in
            scalar.value != 0x0D && scalar.value != 0x0A && scalar.value != 0x00
        }.map { Character($0) }.reduce("") { $0 + String($1) }
    }
}

class DeviceIdentityProvider {
    // Reads device identity from Kubernetes downward API
    // The label value comes from pod annotations set by the device operator
    func getDeviceLabel(from environment: [String: String]) -> String {
        // In K8s, this comes from the Downward API projected volume
        // or environment variable injection from the device CRD
        return environment["DEVICE_LABEL"] ?? "unknown-device"
    }

    func getZoneIdentifier(from environment: [String: String]) -> String {
        return environment["ZONE_ID"] ?? "default-zone"
    }
}

class HealthCheckReporter {
    let config: DeviceConfig
    let identityProvider: DeviceIdentityProvider
    let environment: [String: String]

    init(config: DeviceConfig, identityProvider: DeviceIdentityProvider, environment: [String: String]) {
        self.config = config
        self.identityProvider = identityProvider
        self.environment = environment
    }

    // Constructs the health check HTTP request to send to the
    // cluster's telemetry aggregator service
    func buildHealthCheckRequest() -> String {
        let deviceLabel = identityProvider.getDeviceLabel(from: environment)
        let zoneId = identityProvider.getZoneIdentifier(from: environment)

        // Encode for transport, then decode at request construction time
        // This simulates the encode/decode cycle through the K8s config pipeline
        let encodedLabel = TelemetryEncoder.encodeValue(deviceLabel)
        let encodedZone = TelemetryEncoder.encodeValue(zoneId)

        // The aggregator expects the raw device label in a custom header
        // after transport decoding - sanitize to prevent header injection
        let transportDecodedLabel = HeaderSanitizer.sanitize(TelemetryEncoder.decodeValue(encodedLabel))
        let transportDecodedZone = HeaderSanitizer.sanitize(TelemetryEncoder.decodeValue(encodedZone))

        // Config-derived values also originate from environment variables and
        // must be sanitized before being placed into HTTP headers to prevent
        // header injection via POD_NAMESPACE / POD_NAME.
        let safeNamespace = HeaderSanitizer.sanitize(config.namespace)
        let safePodName = HeaderSanitizer.sanitize(config.podName)
        let safeFirmwareVersion = HeaderSanitizer.sanitize(config.firmwareVersion)

        let headerBuilder = HTTPHeaderBuilder()
        headerBuilder.addHeader(name: "Host", value: "telemetry-aggregator.\(safeNamespace).svc.cluster.local")
        headerBuilder.addHeader(name: "X-Device-Label", value: transportDecodedLabel)
        headerBuilder.addHeader(name: "X-Zone-Id", value: transportDecodedZone)
        headerBuilder.addHeader(name: "X-Firmware-Version", value: safeFirmwareVersion)
        headerBuilder.addHeader(name: "X-Pod-Name", value: safePodName)
        headerBuilder.addHeader(name: "Content-Type", value: "application/json")

        let requestLine = "POST /api/v1/health HTTP/1.1"
        let body = "{\"status\":\"healthy\",\"uptime\":\(ProcessInfo.processInfo.systemUptime)}"

        headerBuilder.addHeader(name: "Content-Length", value: "\(body.utf8.count)")

        let request = "\(requestLine)\r\n\(headerBuilder.build())\r\n\r\n\(body)"
        return request
    }
}

// Kubernetes liveness probe handler
class LivenessProbeHandler {
    let reporter: HealthCheckReporter

    init(reporter: HealthCheckReporter) {
        self.reporter = reporter
    }

    func handleProbe() -> String {
        let request = reporter.buildHealthCheckRequest()
        // In production, this would be sent over a Unix socket to the
        // telemetry aggregator sidecar
        return request
    }
}

// Entry point - simulates firmware boot sequence
func bootFirmware(env: [String: String]) -> String {
    let config = DeviceConfig(
        clusterName: env["CLUSTER_NAME"] ?? "default",
        namespace: env["POD_NAMESPACE"] ?? "iot-devices",
        podName: env["POD_NAME"] ?? "device-pod-0"
    )

    let identityProvider = DeviceIdentityProvider()
    let reporter = HealthCheckReporter(config: config, identityProvider: identityProvider, environment: env)
    let probeHandler = LivenessProbeHandler(reporter: reporter)

    return probeHandler.handleProbe()
}

